"use client";
import { useRouter, usePathname, useSearchParams } from "next/navigation";

function ProductListPage({ total }: { total: number }) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();
  const { state, hasNext, canonical } = parseListParams(searchParams.toString(), total);

  function goTo(patch: Partial<ListState>) {
    const next = { ...state, ...patch };
    const { canonical } = parseListParams(toSearch(next), total); // same rules both ways
    router.push(`${pathname}${canonical}`);
  }

  const { data } = useQuery({
    queryKey: ["products", "list", state],        // the URL state is the query key
    queryFn: () => api.listProducts(state),
    placeholderData: keepPreviousData,            // keep the old page while the next loads
  });

  return <button disabled={!hasNext} onClick={() => goTo({ page: state.page + 1 })}>Next</button>;
}
